package analysis

import (
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"testing"
)

func TestGeneratedFlag(t *testing.T) {
	dir := t.TempDir()
	files := map[string]string{
		"gen.go":        "// Code generated by x. DO NOT EDIT.\n\npackage p\n",
		"gen_test.go":   "// Code generated by x. DO NOT EDIT.\n\npackage p\n",
		"gorefactor.go": "// This file was generated by gorefactor.\n\npackage p\n",
		"late.go":       "package p\n\n// Code generated by x. DO NOT EDIT.\n",
	}
	for name, content := range files {
		err := os.WriteFile(filepath.Join(dir, name), []byte(content), 0o644)
		if err != nil {
			t.Fatal(err)
		}
	}

	parser := NewParser(slog.New(slog.NewTextHandler(io.Discard, nil)))
	pkg, err := parser.ParsePackage(dir)
	if err != nil {
		t.Fatal(err)
	}

	if !pkg.Files["gen.go"].Generated {
		t.Error("gen.go: want Generated")
	}
	if !pkg.TestFiles["gen_test.go"].Generated {
		t.Error("gen_test.go: want Generated")
	}
	if pkg.Files["gorefactor.go"].Generated {
		t.Error("gorefactor.go: 'was generated by' header must not count")
	}
	if pkg.Files["late.go"].Generated {
		t.Error("late.go: header after the package clause must not count")
	}
}

func TestSourceTree_ReplaceRefreshesGenerated(t *testing.T) {
	tree, dir := newTreeWithDir(t, map[string]string{"a.go": "package a\n"})
	path := filepath.Join(dir, "a.go")
	if tree.File(path).Generated {
		t.Fatal("plain file must not be Generated")
	}

	write := func(s string) {
		t.Helper()
		err := os.WriteFile(path, []byte(s), 0o644)
		if err != nil {
			t.Fatal(err)
		}
	}
	write("// Code generated by x. DO NOT EDIT.\n\npackage a\n")
	got, err := tree.Replace(path)
	if err != nil || !got.Generated {
		t.Fatalf("after adding header: Generated=%v err=%v", got != nil && got.Generated, err)
	}
	write("package a\n")
	got, err = tree.Replace(path)
	if err != nil || got.Generated {
		t.Fatalf("after removing header: Generated=%v err=%v", got != nil && got.Generated, err)
	}
}
